101	  var resultsEl    = document.getElementById('orch-preflight-results');
102	
103	  var allChecksPassed = false;
104	
105	  // 4. Render preflight results checklist.
106	  function renderPreflightResults(checks) {
107	    if (!checks || !checks.length) {
108	      resultsEl.innerHTML = '';
109	      allChecksPassed = false;
110	      startBtn.disabled = true;
111	      return;
112	    }
113	    allChecksPassed = checks.every(function (c) { return c.pass; });
114	    startBtn.disabled = !allChecksPassed;
115	    if (!startBtn.disabled) startBtn.textContent = 'Start Run';
116	
117	    var html = '<ul class="preflight-list">';
118	    checks.forEach(function (c) {
119	      var cls = c.pass ? 'preflight-pass' : 'preflight-fail';
120	      html += '<li class="preflight-check ' + cls + '">';
121	      html += '<span class="preflight-icon">' + (c.pass ? '✓' : '✗') + '</span>';
122	      html += ' <strong>' + escapeHtml(c.name) + '</strong>: ' + escapeHtml(c.detail);
123	      if (!c.pass && c.fix) {
124	        html += ' <span class="preflight-fix">Fix: <code>' + escapeHtml(c.fix) + '</code></span>';
125	      }
126	      html += '</li>';
127	    });
128	    html += '</ul>';
129	    resultsEl.innerHTML = html;
130	  }
131	
132	  // 5. Preflight button handler.
133	  preflightBtn.addEventListener('click', function () {
134	    var planPath = planInput.value.trim();
135	    if (!planPath) { window.alert('Please enter a plan path.'); return; }
136	
137	    preflightBtn.disabled = true;
138	    preflightBtn.textContent = 'Running…';
139	    resultsEl.innerHTML = '<p class="text-muted">Running preflight checks…</p>';
140	    allChecksPassed = false;
141	    startBtn.disabled = true;
142	
143	    API.orchestratorStart(planPath, true).then(function (result) {
144	      renderPreflightResults((result && result.checks) ? result.checks : []);
145	    }).catch(function (err) {
146	      resultsEl.innerHTML = '<p class="error-banner">Preflight error: ' +
147	        escapeHtml((err && err.message) ? err.message : String(err)) + '</p>';
148	    }).then(function () {
149	      preflightBtn.disabled = false;
150	      preflightBtn.textContent = 'Run Preflight';
151	    });
152	  });
153	
154	  /**
155	   * Handles the Start Run button click: validates state, calls the API to
156	   * start the orchestrator, then either shows a success banner + status-poll
157	   * timer, or falls back to re-rendering the preflight checklist on failure.
158	   *
159	   * Closure dependencies (from renderOrchestrator() scope):
160	   *   `allChecksPassed`          — guards against starting when preflight has
161	   *                                not passed; mutated to false after a successful
162	   *                                launch so the button cannot be clicked twice.
163	   *   `refreshQueue`             — called immediately after a successful launch
164	   *                                to populate the queue with the new entry;
165	   *                                read-only (function reference).
166	   *   `renderPreflightResults`   — called when the server re-evaluates checks on
167	   *                                a failed start attempt; read-only (function
168	   *                                reference).
169	   *   `_orchStatusPollCleanups`  — the module-level status-poll cleanup registry;
170	   *                                the new setInterval cleanup callback is pushed
171	   *                                here so it is cancelled on full re-render;
172	   *                                mutated.
173	   *
174	   * @param {HTMLButtonElement} startBtn  - The #orch-start-btn element.
175	   * @param {HTMLInputElement}  planInput - The #orch-plan-path input element.
176	   * @param {HTMLElement}       resultsEl - The #orch-preflight-results container.
177	   */
178	  function _handleStartRun(startBtn, planInput, resultsEl) {
179	    var planPath = planInput.value.trim();
180	    if (!planPath || !allChecksPassed) return;
181	
182	    startBtn.disabled = true;
183	    startBtn.textContent = 'Starting…';
184	
185	    API.orchestratorStart(planPath, false).then(function (result) {
186	      if (result && result.started) {
187	        var runStatusFilename = result.runStatusFilename || null;
188	        planInput.value = '';
189	        resultsEl.innerHTML =
190	          '<p class="success-banner">✓ Orchestrator launched' +
191	          (result.pid ? ' (PID\u00a0' + result.pid + ')' : '') +
192	          '. Waiting for the run to appear in the queue below…</p>';
193	        allChecksPassed = false;
194	        startBtn.disabled = true;
195	        refreshQueue();
196	
197	        // Poll the run-status tombstone so we can surface fatal early
198	        // failures (e.g. invalid API key) that complete before the first
199	        // queue poll cycle.
200	        if (runStatusFilename) {
201	          var pollCount = 0;
202	          var MAX_STATUS_POLLS = 15; // 2s × 15 = 30s window
203	          var statusPollTimer = setInterval(function () {
204	            pollCount++;
205	            API.orchestratorGetRunStatus(runStatusFilename).then(function (status) {
206	              if (!status) return; // file not yet written — run still in progress
207	              clearInterval(statusPollTimer);
208	              if (status.result === 'ERROR' && status.error) {
209	                resultsEl.innerHTML =
210	                  '<p class="error-banner">Run failed: ' +
211	                  escapeHtml(status.error) + '</p>';
212	              }
213	              // SUCCESS: queue will reflect the project; leave the banner.
214	            }).catch(function () {
215	              // Transient error — keep polling.
216	            });
217	            if (pollCount >= MAX_STATUS_POLLS) {
218	              clearInterval(statusPollTimer);
219	            }
220	          }, 2000);
221	          _orchStatusPollCleanups.push(function () { clearInterval(statusPollTimer); });
222	        }
223	      } else {
224	        // Checks re-evaluated by server — update the checklist.
225	        renderPreflightResults((result && result.checks) ? result.checks : []);
226	      }
227	    }).catch(function (err) {
228	      window.alert('Failed to start: ' + ((err && err.message) ? err.message : String(err)));
229	      startBtn.disabled = !allChecksPassed;
230	      startBtn.textContent = 'Start Run';
231	    }).then(function () {
232	      startBtn.textContent = 'Start Run';
233	    });
234	  }
235	
236	  // 6. Start Run button handler.
237	  startBtn.addEventListener('click', function () { _handleStartRun(startBtn, planInput, resultsEl); });
238	
239	  // 7. Queue refresh and rendering — tracks expanded row IDs across refreshes.
240	  var expandedIds = {};
241	
242	  function refreshQueue() {
243	    // Stop log preview intervals started in the previous queue render.
244	    _orchLogPreviewCleanups.forEach(function (fn) { try { fn(); } catch (_) {} });
245	    _orchLogPreviewCleanups = [];
246	
247	    var container = document.getElementById('orch-queue-container');
248	    if (!container) return;
249	
250	    API.orchestratorGetQueue().then(function (entries) {
251	      renderQueueTable(container, Array.isArray(entries) ? entries : []);
252	    }).catch(function () {
253	      // Best-effort polling — keep existing content on transient errors.
254	    });
255	  }
256	
257	  // ---- renderQueueTable helpers (closure-scoped) ----------------------------
258	
259	  /** Removes the success banner from the preflight results area, if present.
260	   *  Error banners are intentionally left intact.
261	   *
262	   *  Closure dependency: `resultsEl` — the #orch-preflight-results element
263	   *  captured by renderOrchestrator() at line 64. */
264	  function _clearSuccessBanner() {
265	    var successBanner = resultsEl.querySelector('.success-banner');
266	    if (successBanner) {
267	      successBanner.remove();
268	    }
269	  }
270	
271	  /** Builds the queue table HTML string from the entries array.
272	   *  Returns the complete <table>…</table> markup ready to be assigned to
273	   *  container.innerHTML. */
274	  function _buildQueueHtml(entries) {
275	    var html = '<table class="table orch-queue-table"><thead>' +
276	      '<tr><th></th><th>Plan</th><th>Status</th><th>Elapsed</th><th>Progress</th><th>Actions</th></tr>' +
277	      '</thead><tbody>';
278	    entries.forEach(function (entry) {
279	      var id         = entry.id || '';
280	      var status     = entry.effectiveStatus || 'pending';
281	      var planName   = _orchBasename(entry.planPath || '');
282	      var elapsed    = _orchElapsed(entry.startedAt);
283	      var isExpanded = !!expandedIds[id];
284	      var statusBadgeHtml = '<span class="badge badge-' + escapeHtml(status) + '">' +
285	        escapeHtml(_orchStatusLabel(status)) + '</span>';
286	      // Progress cell: badge + text summary + optional log link.
287	      var progressHtml = OrchestratorWidgets.renderProgressBadge(entry.lastAction || null);
288	      if (entry.progress) {
289	        progressHtml += ' <span class="orch-progress-text">' + escapeHtml(entry.progress) + '</span>';
290	      }
291	      if (entry.logFilename && entry.expectedSlug) {
292	        progressHtml += ' <a href="#/projects/' +
293	          encodeURIComponent(entry.expectedSlug) + '/runs/' +
294	          encodeURIComponent(entry.logFilename) + '" class="orch-log-link">View Log →</a>';
295	      } else if (!entry.progress) {
296	        progressHtml += ' <span class="text-muted">Waiting for log…</span>';
297	      }
298	      html += '<tr class="orch-queue-row orch-row-' + escapeHtml(status) + '"' +
299	        ' data-entry-id="' + escapeHtml(id) + '">';
300	      html += '<td class="orch-toggle-cell">' +

301	        '<button type="button" class="orch-row-toggle btn-icon" data-entry-id="' + escapeHtml(id) + '">' +
302	        (isExpanded ? '▼' : '▶') + '</button></td>';
303	      html += '<td class="orch-plan-cell" title="' + escapeHtml(entry.planPath || '') + '">' +
304	        escapeHtml(planName) + '</td>';
305	      html += '<td class="orch-status-cell">' + statusBadgeHtml + '</td>';
306	      html += '<td class="orch-elapsed-cell">' + escapeHtml(elapsed) + '</td>';
307	      html += '<td class="orch-progress-cell">' + progressHtml + '</td>';
308	      html += '<td class="orch-actions-cell" data-actions-for="' + escapeHtml(id) + '"></td>';
309	      html += '</tr>';
310	      if (isExpanded) {
311	        html += '<tr class="orch-log-row" data-entry-id="' + escapeHtml(id) + '">' +
312	          '<td colspan="6">' +
313	          '<div class="orch-log-preview" id="orch-log-' + escapeHtml(id) + '"></div>' +
314	          '</td></tr>';
315	      }
316	    });
317	    html += '</tbody></table>';
318	    return html;
319	  }
320	
321	  /** Injects DOM-based action buttons and toggle listeners into the rendered
322	   *  table. Must be called after container.innerHTML has been set.
323	   *
324	   *  Branch priority (dismissibility-first):
325	   *    1. pending  → Kill button   (process is still running)
326	   *    2. dead     → Dismiss button (process has exited without completing)
327	   *    3. projectExists → View Project link (project ledger is on disk)
328	   *  The dead branch precedes the projectExists branch so that a dead entry
329	   *  that also has a known project slug always renders Dismiss, not View Project.
330	   *
331	   *  Closure dependencies (from renderOrchestrator() scope):
332	   *    `expandedIds`            — tracks which queue rows are expanded; mutated
333	   *                               by toggle clicks to persist state across refreshes.
334	   *    `refreshQueue`           — triggers a fresh API fetch + re-render after
335	   *                               a Kill/Dismiss action or toggle click. */
336	  function _bindQueueActions(container, entries) {
337	    entries.forEach(function (entry) {
338	      var id     = entry.id || '';
339	      var status = entry.effectiveStatus || 'pending';
340	      var cell   = container.querySelector('[data-actions-for="' + id + '"]');
341	      if (!cell) return;
342	
343	      if (status === 'pending') {
344	        cell.appendChild(OrchestratorWidgets.renderKillButton(id, function () {
345	          delete expandedIds[id];
346	          refreshQueue();
347	        }));
348	      } else if (status === 'dead') {
349	        cell.appendChild(OrchestratorWidgets.renderDismissButton(id, function () {
350	          delete expandedIds[id];
351	          refreshQueue();
352	        }));
353	      } else if (entry.projectExists === true && entry.expectedSlug) {
354	        var link = document.createElement('a');
355	        link.href = '#/projects/' + encodeURIComponent(entry.expectedSlug);
356	        link.className = 'btn btn-sm btn-secondary orch-project-link';
357	        link.textContent = 'View Project';
358	        cell.appendChild(link);
359	      }
360	    });
361	
362	    var toggleBtns = container.querySelectorAll('.orch-row-toggle');
363	    Array.prototype.forEach.call(toggleBtns, function (btn) {
364	      btn.addEventListener('click', function () {
365	        var id = btn.getAttribute('data-entry-id');
366	        if (id) expandedIds[id] = !expandedIds[id];
