453	    if (isNaN(diff) || diff < 0) return '—';
454	    var secs = Math.round(diff / 1000);
455	    if (secs < 60)  return secs + 's';
456	    var mins = Math.floor(secs / 60);
457	    if (mins < 60)  return mins + 'm ' + (secs % 60) + 's';
458	    return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
